from django.core.cache import cache
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from rest_framework.exceptions import PermissionDenied

class UpdateCachedDashboardView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        target_user_id = request.data.get('user_id')
        layout_data = request.data.get('layout')
        if not target_user_id or not layout_data:
            return Response({'error': 'user_id and layout required'}, status=status.HTTP_400_BAD_REQUEST)

        if str(target_user_id) != str(request.user.id):
            raise PermissionDenied("You can only modify your own dashboard layout.")

        cache_key = f"dashboard_layout_{target_user_id}"
        cache.set(cache_key, layout_data, timeout=86400)
        return Response({'status': 'saved', 'user_id': target_user_id})
